        if (n < 0) {
            perror("ERROR in recvfrom");
        } else {
            // --- Protocol Parsing ---

            // 1. Read Event Count (4 bytes, big-endian uint32)
            uint32_t event_count;
            memcpy(&event_count, buffer, sizeof(uint32_t));
            event_count = ntohl(event_count); // Convert network byte order to host

            if (event_count == 0 || event_count > 100) { // Sanity check
                continue; 
            }

            // 2. Calculate payload size (each event is 2 codes * 2 bytes = 4 bytes)
            size_t payload_size = event_count * 4;

            if (payload_size > (size_t)n - sizeof(uint32_t)) {
                fprintf(stderr, "Buffer too small for declared event count\n");
                continue;
            }

            // 3. Parse Events
            // We expect an array of [Code, Value] pairs
            int16_t *data = (int16_t *)(buffer + sizeof(uint32_t));

            for (uint32_t i = 0; i < event_count; ++i) {
                int16_t code = data[i * 2];
                int16_t value = data[i * 2 + 1];

                // Find matching event name/code
                for (int j = 0; j < sizeof(REGISTERED_EVENTS) / sizeof(REGISTERED_EVENTS[0]); ++j) {
                    if (REGISTERED_EVENTS[j].code == code) {
                        libevdev_uinput_write_event(controller, REGISTERED_EVENTS[j].type,
                                                    REGISTERED_EVENTS[j].code, value);

                        // Handle analog stick updates specifically if needed, 
                        // but libevdev handles reporting correctly for both keys and abs.
                        break;
                    }
                }
            }

            // Send SYN report to flush the event queue immediately
            libevdev_uinput_write_event(controller, EV_SYN, SYN_REPORT, 0);

        }
    }

    close(sockfd);
}

int main() {
    controller = controller_create();
    udp_server();
    libevdev_uinput_destroy(controller);
    return 0;
}
