const std = @import("std");
const rl = @import("raylib");
const net = std.net;
const posix = std.posix;

const ControllerEvents = enum(i16) {
    ANALOG_LX = 0,
    ANALOG_LY = 1,
    ANALOG_RX = 2,
    ANALOG_RY = 3,
    L1 = 4,
    L2 = 5,
    R1 = 6,
    R2 = 7,
    TRIANGLE = 8,
    CROSS = 9,
    SQUARE = 10,
    CIRCLE = 11,
    UP = 12,
    DOWN = 13,
    LEFT = 14,
    RIGHT = 15,
    SELECT = 16,
    START = 17,
};

pub fn main() anyerror!void {
    const alloc = std.heap.page_allocator;
    _ = alloc;

    const screenWidth = 800;
    const screenHeight = 450;

    rl.initWindow(screenWidth, screenHeight, "raylib-zig example - keyboard to controller input");
    defer rl.closeWindow();

    rl.setTargetFPS(60);

    const sock = try posix.socket(posix.AF.INET, posix.SOCK.DGRAM, 0);
    defer posix.close(sock);

    var addr = try net.Address.parseIp4("127.0.0.1", 31415);

    while (!rl.windowShouldClose()) {
        // 1. Update State
        var state: [18]i16 = undefined;
        @memset(state, 0);

        state[@intFromEnum(ControllerEvents.UP)] = if (rl.isKeyDown(rl.KeyboardKey.key_up)) 1 else 0;
        state[@intFromEnum(ControllerEvents.DOWN)] = if (rl.isKeyDown(rl.KeyboardKey.key_down)) 1 else 0;
        state[@intFromEnum(ControllerEvents.LEFT)] = if (rl.isKeyDown(rl.KeyboardKey.key_left)) 1 else 0;
        state[@intFromEnum(ControllerEvents.RIGHT)] = if (rl.isKeyDown(rl.KeyboardKey.key_right)) 1 else 0;

        // 2. Construct Packet
        // Protocol: [4 bytes u32 (count)][18 * 4 bytes (pair of i16)]
        var packet: [512]u8 = undefined;
        var offset: usize = 0;

        // Header: Total events (always 18 in this static setup)
        const num_events: u32 = 18;
        std.mem.copyBigEndian(packet[offset..offset+4], num_events);
        offset += 4;

        // Payload: Loop through events
        for (0..18) |i| {
            // Code is the index (0..17)
            // Value is stored in state[i]
            const code: i16 = @intFromEnum(@as(ControllerEvents, @fromInt(i)));
            const val: i16 = state[i];

            // Pack into 4 bytes (Code, Value)
            // Using Little Endian for simplicity (matches Zig default and typical local networking)
            // If you want Network Byte Order (Big Endian) for WAN:
            // Use std.mem.copyBigEndian on the slice.

            var pair_buf: [4]u8 = undefined;
            std.mem.copyLittleEndian(pair_buf[0..2], code);
            std.mem.copyLittleEndian(pair_buf[2..4], val);

            mem.copy(packet[offset..offset+4], pair_buf[0..4]);
            offset += 4;
        }

        // 3. Send
        const sockaddr = &addr.any;
        const addrlen = addr.getOsSockLen();
        const ret = try posix.sendto(sock, &packet[0..offset], 0, sockaddr, addrlen);

        // Optional debug log
        // std.debug.print("Sent {} bytes\n", .{ret});

        // 4. Draw
        rl.beginDrawing();
        rl.clearBackground(rl.Color.white);
        rl.drawText("Press arrow keys to simulate controller input!", 190, 200, 20, rl.Color.light_gray);
        rl.endDrawing();
    }
}
```

### Summary of Changes

1.  **Server (`server.c`)**:
    *   Reads a `uint32_t` header first to determine how many event pairs follow.
    *   Calculates payload size dynamically (`count * 4`).
    *   Loops `count` times, reading two `int16_t`s per iteration (Code, Value).
    *   Matches the Code against `REGISTERED_EVENTS` to trigger the correct virtual event.

2.  **Client (`client.zig`)**:
    *   Constructs a fixed-size buffer.
    *   Writes a `uint32_t` header indicating the number of events (18).
    *   Iterates through the 18 event slots, extracting the `Code` (the index) and `Value` (from the state array).
    *   Packs them into `[Code, Value]` pairs and appends them to the buffer.
    *   Sends the resulting buffer via `sendto`.

This ensures that whether the user presses 1 key or 18 keys, the server receives exactly what it needs to interpret the input correctly.

